scripts.continued_fraction:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Initialize for continued fraction numerator calculation
    # p_{-1} = 1, p_0 = a_0
    p_prev = 1  # p_{-1}
    p = terms[0]  # p_0

    # Apply recurrence relation: p_n = a_n * p_{n-1} + p_{n-2}
    for i in range(1, len(terms)):
        p_next = terms[i] * p + p_prev
        p_prev = p
        p = p_next

    return float(p)

scripts.gcd_list:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values in the list
    result = values[0]
    for val in values[1:]:
        result = math.gcd(result, val)

    return float(result)

scripts.sum_quotients:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor divisions
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod m
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i, j) where i < j and values[i] > values[j]
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

